/bin/bash -lc "python3 - <<'PY'
try: import cv2; print('cv2',cv2.__version__)
except Exception as e: print(e)
from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB'))
# unique-ish sampled kmeans cv2
import cv2
s=im[::3,::3].reshape(-1,3).astype(np.float32)
crit=(cv2.TERM_CRITERIA_EPS+cv2.TERM_CRITERIA_MAX_ITER,50,0.2)
_,lab,cen=cv2.kmeans(s,16,None,crit,5,cv2.KMEANS_PP_CENTERS)
counts=np.bincount(lab[:,0],minlength=16)
for i in np.argsort(counts)[::-1]: print(counts[i], cen[i].astype(int))
# coarse segmentation ascii nearest clusters at blocks center averages 20x20
C=cen; chars='0123456789ABCDEF'
# map sorted cluster rank to a char, print lookup
order=np.argsort(counts)[::-1]; mp={int(v):chars[i] for i,v in enumerate(order)}
print('lookup');
for v in order: print(mp[int(v)],cen[v].astype(int),counts[v])
small=cv2.resize(im,(80,45),interpolation=cv2.INTER_AREA).reshape(-1,3)
labels=((small[:,None]-C[None])**2).sum(2).argmin(1).reshape(45,80)
for row in labels: print(''.join(mp[int(v)] for v in row))
PY"
